// Static documentation: the catalogue is generated by examples/padview_api_catalogue.rs.
const el = (tag, text) => Object.assign(document.createElement(tag), {textContent: text ?? ''});
async function catalogue() {
  const response = await fetch('./api-catalogue.json');
  if (!response.ok) throw Error('HTTP ' + response.status);
  const data = await response.json();
  const components = document.querySelector('#api-components');
  const list = el('dl');
  for (const [name, rows] of [['组件类型与默认正文', data.component_types], ['中心读数', data.component_center_sources],
      ['可选字体', data.component_fonts], ['达成率算法', data.component_achievement_modes]]) {
    list.append(el('dt', name));
    const line = el('dd');
    for (const item of rows) {
      const tag = el('span'); tag.className = 'api-option';
      tag.append(el('code', JSON.stringify(item.value)), ' ' + item.label);
      if (item.default_template) tag.append(' · ', el('code', item.default_template));
      line.append(tag);
    }
    list.append(line);
  }
  list.append(el('dt', '模板占位符'), el('dd', data.component_template_fields));
  components.append(list);
  const input = document.querySelector('#api-filter'), panel = document.querySelector('#api-fields');
  const groups = new Map(data.groups.map(g => [g.id, g.label]));
  const entries = data.items.map(field => {
    const article = el('div'); article.className = 'api-setting';
    const title = el('b', field.label);
    article.append(title, el('code', field.key));
    const localOnly = field.native_only || ['params.no_core_autoplay','params.judge_offset_ms'].includes(field.key);
    const meta = [field.kind, field.developer && '开发者', localOnly && '仅原生',
      field.min != null && ('范围 ' + field.min + ' 至 ' + field.max + '，步长 ' + field.step)].filter(Boolean);
    article.append(el('small', meta.join(' · ')));
    if (field.help) article.append(el('p', field.help));
    if (field.choices?.length) {
      const choices = el('div');
      for (const {value,label,help} of field.choices) {
        const option = el('span'); option.className = 'api-option';
        option.append(el('code', JSON.stringify(value)), ' ' + label + (help ? '：' + help : ''));
        choices.append(option);
      }
      article.append(choices);
    }
    return {group:field.group, article, search:(groups.get(field.group)+' '+article.textContent).toLowerCase()};
  });
  function filter() {
    const terms = input.value.toLowerCase().trim().split(/\s+/).filter(Boolean);
    const matching = entries.filter(e => terms.every(t => e.search.includes(t)));
    const fragment = document.createDocumentFragment();
    for (const [id,label] of groups) {
      const rows = matching.filter(e => e.group === id);
      if (!rows.length) continue;
      const group = el('details'); group.open = !!terms.length;
      group.append(el('summary', label + ' · ' + rows.length), ...rows.map(r => r.article));
      fragment.append(group);
    }
    panel.replaceChildren(fragment);
    document.querySelector('#api-count').textContent = matching.length + ' / ' + entries.length + ' 项';
  }
  input.addEventListener('input', filter); filter();
}
catalogue().catch(error => { document.querySelector('#api-count').textContent = '目录读取失败：' + error.message; });
